+
+/**
+ * Validate the `next` query param. Allow only same-origin relative paths so we
+ * cannot be tricked into open-redirecting to `//evil.example.com` etc.
+ */
+export function sanitizeNext(raw: string | null): string {
+  if (!raw) return "/";
+  if (!raw.startsWith("/")) return "/";
+  if (raw.startsWith("//")) return "/";
+  if (raw.includes("\\")) return "/";
+  // eslint-disable-next-line no-control-regex
+  if (/[\x00-\x1f]/.test(raw)) return "/";
+  return raw;
+}
+
+export function LoginPage() {
+  const { login, loginGoogle, status } = useAuth();
+  const navigate = useNavigate();
+  const location = useLocation();
+  const params = new URLSearchParams(location.search);
+  const next = sanitizeNext(params.get("next"));
+
+  const [email, setEmail] = React.useState("");
+  const [password, setPassword] = React.useState("");
+  const [submitting, setSubmitting] = React.useState(false);
+  const [error, setError] = React.useState<string | null>(null);
+
+  React.useEffect(() => {
+    if (status === "authenticated") {
+      navigate(next, { replace: true });
+    }
+  }, [status, navigate, next]);
+
+  const onSubmit = async (e: React.FormEvent) => {
+    e.preventDefault();
+    setError(null);
+    setSubmitting(true);
+    try {
+      await login(email, password);
+      navigate(next, { replace: true });
+    } catch (err) {
+      const message = err instanceof Error ? err.message : "登入失敗";
+      setError(message);
+    } finally {
+      setSubmitting(false);
+    }
+  };
+
+  return (
+    <div className="flex min-h-screen items-center justify-center bg-muted/30 px-4">
+      <Card className="w-full max-w-sm">
+        <CardHeader>
+          <CardTitle>登入 AI API Manager</CardTitle>
+          <CardDescription>用組織帳號或本機密碼登入</CardDescription>
+        </CardHeader>
+        <CardContent className="space-y-4">
+          {error && (
+            <Alert variant="destructive" data-testid="login-error">
+              <AlertDescription>{error}</AlertDescription>
+            </Alert>
+          )}
+
+          <form onSubmit={onSubmit} className="space-y-3" aria-label="local-login-form">
+            <div className="space-y-1.5">
+              <Label htmlFor="email">Email</Label>
+              <Input
+                id="email"
+                type="email"
+                autoComplete="email"
+                required
+                value={email}
+                onChange={(e) => setEmail(e.target.value)}
+              />
+            </div>
+            <div className="space-y-1.5">
+              <Label htmlFor="password">密碼</Label>
+              <Input
+                id="password"
+                type="password"
+                autoComplete="current-password"
+                required
+                value={password}
+                onChange={(e) => setPassword(e.target.value)}
+              />
+            </div>
+            <Button type="submit" className="w-full" disabled={submitting}>
+              {submitting ? "登入中…" : "登入"}
+            </Button>
+          </form>
+
+          <div className="relative">
+            <div className="absolute inset-0 flex items-center">
+              <span className="w-full border-t" />
+            </div>
+            <div className="relative flex justify-center text-xs uppercase">
+              <span className="bg-card px-2 text-muted-foreground">或</span>
+            </div>
+          </div>
+
+          <Button variant="outline" className="w-full" onClick={loginGoogle}>
+            使用 Google 登入
+          </Button>
+        </CardContent>
+      </Card>
+    </div>
+  );
+}

